  "request_id": "gen-20261115T080625-5b263d",
  "peers": ["INTC", "AMAT", "LRCX", "KLAC"],
  "dcf_weight": 0.75,
  "dcf": {
    "wacc": 0.105,
    "terminal_growth": 0.03,
